import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    t = int(input_data[0])
    results = []
    idx = 1
    for _ in range(t):
        if idx >= len(input_data):
            break
        s = input_data[idx]
        idx += 1
        n = len(s)
        if n % 2 == 1:
            results.append("YES")  # Should not happen per guarantee
            continue

        open_count = s.count('(')
        close_count = s.count(')')
        q_count = n - open_count - close_count

        k = n // 2 - open_count  # number of ? that must be '('

        if k == 0 or k == q_count:
            # All ? are forced to same type
            results.append("YES")
        else:
            # Build canonical assignment: first k ? become '(', rest become ')'
            canonical = list(s)
            q_positions = []
            for i, ch in enumerate(s):
                if ch == '?':
                    q_positions.append(i)

            # Fill canonical
            for i in range(k):
                canonical[q_positions[i]] = '('
            for i in range(k, q_count):
                canonical[q_positions[i]] = ')'
            canonical_str = ''.join(canonical)

            # Check if canonical is valid (guaranteed to be by problem statement + construction)
            # Now check if swapping the rightmost '(' among ? (at q_positions[k-1])
            # with the leftmost ')' among ? (at q_positions[k]) produces a valid RBS
            # This is the "least likely to be valid" swap if any swap works.

            test_chars = list(canonical_str)
            test_chars[q_positions[k-1]] = ')'  # was '(' becomes ')'
            test_chars[q_positions[k]] = '('    # was ')' becomes '('
            test_str = ''.join(test_chars)

            balance = 0
            is_valid = True
            for ch in test_str:
                if ch == '(':
                    balance += 1
                elif ch == ')':
                    balance -= 1
                if balance < 0:
                    is_valid = False
                    break
            if is_valid and balance == 0:
                results.append("NO")  # Multiple valid ways exist
            else:
                results.append("YES")  # Only canonical way exists

    for r in results:
        print(r)

if __name__ == "__main__":
    solve()
